def set_widths(t, total_in=6.5):
    n = len(t.columns)
    if n == 0: return
    weights = []
    header_lens = []
    for ci in range(n):
        mx = 0
        for r in t.rows:
            try:
                txt = r.cells[ci].text
            except IndexError:
                txt = ""
            mx = max(mx, min(len(txt), 160))
        weights.append(max(mx, 6) ** 0.85)
        try:
            hl = len(t.rows[0].cells[ci].text)
        except IndexError:
            hl = 0
        try:
            fl = len(t.rows[1].cells[ci].text) if len(t.rows) > 1 else 0
        except IndexError:
            fl = 0
        header_lens.append(min(max(hl, fl if fl < 26 else 0), 26))
    ssum = sum(weights)
    floors = []
    widths = []
    for ci, w in enumerate(weights):
        floor = max(0.55, 0.065 * header_lens[ci] + 0.22)
        floors.append(floor)
        widths.append(max(floor, total_in * w / ssum))
    total = sum(widths)
    if total > total_in:
        excess = total - total_in
        for _ in range(50):
            slack = [max(0.0, widths[i] - floors[i]) for i in range(n)]
            ssum2 = sum(slack)
            if ssum2 <= 0.01 or excess <= 0.001:
                break
            take = min(excess, ssum2)
            for i in range(n):
                widths[i] -= take * slack[i] / ssum2
            excess -= take
    else:
        widths[widths.index(max(widths))] += (total_in - total)
    fixed_layout(t)
    for ci, w in enumerate(widths):
        t.columns[ci].width = Inches(w)
    for r in t.rows:
        for ci, w in enumerate(widths):
            try:
                r.cells[ci].width = Inches(w)
            except IndexError:
                pass

